import React from "react";

const Hero = () => {
  return (
    <div>
      <div className="container text-center mt-5 mb-5">
        <h1>Open a free demat & trading account online</h1>
        <p className="text-muted font-bold">
          Start investing brokerage free and join a community of 1.5+ crore
          investors and traders
        </p>
      </div>
      <div className="flex flex-row">
        <div className="col-4" >
            <img src="assets/signup.svg" alt="" />
        </div>
        <div className="col-4">
            <h1>Signup now</h1>
            <h3>Or track your existing application</h3>
            <input type="text border"/>
        </div>
      </div>
    </div>
  );
};

export default Hero;
